from __future__ import annotations


def _value(source: dict | None, key: str) -> object:
    if not source:
        return ""
    value = source.get(key, "")
    return "" if value is None else value


def _nvl(value: object, default: object) -> object:
    return default if value is None or value == "" else value


def _number(value: object) -> float:
    if value is None or value == "":
        return 0.0
    return float(value)


def _text(value: object) -> str:
    return "" if value is None else str(value)


def _numeric_equal(left: object, right: object) -> bool:
    return _number(left) == _number(right)


def _date_equal(left: object, right: str) -> bool:
    left_text = _text(left)
    if left_text == "00000000" or right == "00000000":
        return left_text == right == "00000000"
    return left_text == right


def _date_ge(left: object, right: str) -> bool:
    left_text = _text(left)
    if left_text == "00000000" or right == "00000000":
        return False
    return left_text >= right


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    errors: list[dict] = []

    def fail(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append({"code": code, "message": message, "severity": severity})

    status = _text(_value(record, "STAT_CD"))
    amount = _value(record, "AMT")
    lost_reason = _text(_value(record, "LOST_RSN"))
    close_date = _value(record, "CLOSE_DT")
    stage_pct = _value(record, "STAGE_PCT")

    # OPP-001
    if not (_number(_nvl(amount, 0)) >= 0):
        fail("E3001", "Amount negative")

    # OPP-002
    if not (status == "W" and _numeric_equal(_nvl(amount, 0), 0)):
        pass
    else:
        fail("E3002", "Won opportunity requires amount")

    # OPP-003
    if not (status == "L" and lost_reason == ""):
        pass
    else:
        fail("E3003", "Lost reason required")

    # OPP-004
    if not (status == "W" and _date_equal(close_date, "00000000")):
        pass
    else:
        fail("E3004", "Won opportunity requires close date")

    # OPP-005
    if event == "UPDATE":
        old_status = _text(_value(old, "STAT_CD"))
        if old_status == "W" and status != "W":
            fail("E3005", "Cannot reopen a won opportunity")

    # OPP-006
    stage_consistent = (
        (status == "P" and _numeric_equal(stage_pct, 10))
        or (status == "Q" and _numeric_equal(stage_pct, 25))
        or (status == "N" and _numeric_equal(stage_pct, 60))
        or (status == "W" and _numeric_equal(stage_pct, 100))
        or (status == "L" and _numeric_equal(stage_pct, 0))
    )
    if not stage_consistent:
        fail("E3006", "Stage percent inconsistent with status")

    # OPP-007
    if event == "INSERT":
        if not (
            _date_equal(close_date, "00000000")
            or _date_ge(close_date, today)
        ):
            fail("E3007", "Close date in past", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
